
.exposure-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.gauges {
  display: flex;
  gap: 8px;
}

.gauge {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 8px 4px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
}

.gauge-label {
  font-size: 11px;
  color: var(--c-text-dim);
}

.gauge-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--c-accent);
}

.gauge-value.danger {
  color: var(--c-danger);
}

.block {
  border: 1px solid var(--c-border);
  border-radius: 6px;
  background: var(--c-surface);
  overflow: hidden;
}

.block-title {
  padding: 6px 10px;
  font-size: 12px;
  color: var(--c-text-dim);
  background: var(--c-surface-2);
  border-bottom: 1px solid var(--c-border);
}

.row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 10px;
  border-bottom: 1px solid var(--c-border);
}

.row:last-child {
  border-bottom: none;
}

.label {
  color: var(--c-text-dim);
  flex-shrink: 0;
}

.value {
  color: var(--c-text);
  text-align: right;
  word-break: break-all;
}
