
.map-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.map {
  width: 100%;
  height: auto;
  display: block;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
}

.metro-line {
  stroke: var(--c-border);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 6 5;
}

.area {
  fill: var(--c-surface-2);
  stroke: var(--c-border);
  stroke-width: 1.5;
  transition: fill 0.2s, stroke 0.2s;
}

.area.current {
  fill: rgba(224, 107, 158, 0.22);
  stroke: var(--c-accent);
  stroke-width: 2;
}

.area-label {
  fill: var(--c-text-dim);
  font-size: 12px;
  pointer-events: none;
}

.area.current .area-label {
  fill: var(--c-accent);
}

.location-text {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-safe);
  flex-shrink: 0;
}

.dot.moving {
  background: var(--c-accent);
}
